describe("gsap scroll source producer seam", () => {
  it("treats duplicate callbacks as independent subscriptions", async () => {
    const { created, scrollTrigger } = fakeScrollTrigger();
    const source = createGsapScrollSource(scrollTrigger, { trigger: "#scene" });
    const seen: number[] = [];
    const notify = (p: number) => { seen.push(p); };
    const first = source.subscribe(notify);
    const second = source.subscribe(notify);
    await Promise.resolve();
    expect(seen).toEqual([0, 0]);
    seen.length = 0;
    first(); first();
    created[0]!.emit(0.5);
    expect(seen).toEqual([0.5]);
    expect(created[0]!.killed()).toBe(false);
    second();
    expect(created[0]!.killed()).toBe(true);
  });

  it("attempts remaining listeners and preserves a single thrown value without replay", async () => {
    const { created, scrollTrigger } = fakeScrollTrigger();
    const source = createGsapScrollSource(scrollTrigger, { trigger: "#scene" });
    const failure = new Error("listener failed");
    const seen: number[] = [];
    const first = source.subscribe(p => { if (p !== 0) throw failure; });
    const second = source.subscribe(p => { seen.push(p); });
    await Promise.resolve();
    seen.length = 0;
    expect(() => created[0]!.emit(0.6)).toThrow(failure);
    expect(seen).toEqual([0.6]);
    await Promise.resolve();
    expect(seen).toEqual([0.6]);
    first(); second();
  });

  it("a reentrant update supersedes the remaining older fan-out", async () => {
    const { created, scrollTrigger } = fakeScrollTrigger();
    const source = createGsapScrollSource(scrollTrigger, { trigger: "#scene" });
    const seen: number[] = [];
    const first = source.subscribe(p => { if (p === 0.6) created[0]!.emit(0.8); });
    const second = source.subscribe(p => { seen.push(p); });
    await Promise.resolve(); seen.length = 0;
    created[0]!.emit(0.6);
    expect(seen).toEqual([0.8]);
    first(); second();
  });

  it("a subscription created during fan-out waits for its fresh initial snapshot", async () => {
    const { created, scrollTrigger } = fakeScrollTrigger();
    const source = createGsapScrollSource(scrollTrigger, { trigger: "#scene" });
    const seen: number[] = [];
    let detachLate = () => {};
    const first = source.subscribe(p => { if (p === 0.6) detachLate = source.subscribe(value => { seen.push(value); }); });
    await Promise.resolve();
    created[0]!.emit(0.6);
    expect(seen).toEqual([]);
    await Promise.resolve();
    expect(seen).toEqual([0.6]);
    first(); detachLate();
  });

describe("T3 scroll driver", () => {
  it("routes the GSAP restored snapshot through the factory and scheduler, never load or mount", async () => {
    const producer = { progress: 0.6, scroll: () => 600, kill() {} };
    const scroll = createGsapScrollSource({ create: () => producer }, { trigger: "#scene" });
    const { handle, scheduler } = load(() => scroll, [scrollMotion()]);
    handle.mount("scene/arm");
    const beforeDriver = handle.get("scene/arm");
    scheduler.flush();
    expect(handle.get("scene/arm")).toEqual(beforeDriver);
    await Promise.resolve();
    expect(handle.get("scene/arm")).toEqual(beforeDriver);
    scheduler.flush();
    expect(handle.get("scene/arm")?.values).toEqual({ x: 60 });
    handle.dispose();
  });

  it("shares one producer across motions, holds refresh and normalizes only in the port", async () => {
    let vars: Record<string, unknown> = {};
    let position = 500; let kills = 0; let creates = 0;
    const producer = { progress: 1.4, scroll: () => position, kill() { kills++; } };
    const scroll = createGsapScrollSource({ create: options => { creates++; vars = options; return producer; } }, { trigger: "#scene" });
    const emit = (key: string) => (vars[key] as (() => void))();
    const { handle, scheduler } = load(() => scroll, [scrollMotion("first"), scrollMotion("second")]);
    handle.mount("first/arm"); handle.mount("second/arm");
    await Promise.resolve(); scheduler.flush();
    expect(creates).toBe(1);
    expect(handle.get("first/arm")?.values).toEqual({ x: 100 });
    expect(handle.get("second/arm")?.values).toEqual({ x: 100 });
    emit("onRefreshInit"); producer.progress = 0.25; emit("onUpdate"); emit("onRefresh");
    scheduler.flush();
    expect(handle.get("first/arm")?.values).toEqual({ x: 100 });
    producer.progress = -0.2; position = 100; emit("onUpdate"); scheduler.flush();
    expect(handle.get("first/arm")?.values).toEqual({ x: 0 });
    expect(handle.get("second/arm")?.values).toEqual({ x: 0 });
    producer.progress = Number.NaN; position = 200;
    expect(() => emit("onUpdate")).toThrow(AggregateError);
    producer.progress = 0.3; position = 300; emit("onUpdate"); scheduler.flush();
    expect(handle.get("second/arm")?.values).toEqual({ x: 30 });
    handle.dispose();
    expect(kills).toBe(1);
    expect(() => emit("onUpdate")).not.toThrow();
  });

  it("disposal before the GSAP initial microtask cancels both Motion consumers", async () => {
    let kills = 0;
    const scroll = createGsapScrollSource({ create: () => ({ progress: 0.6, scroll: () => 600, kill() { kills++; } }) }, { trigger: "#scene" });
    const { handle, scheduler } = load(() => scroll, [scrollMotion("first"), scrollMotion("second")]);
    handle.dispose();
    await Promise.resolve();
    expect(() => scheduler.flush()).not.toThrow();
    expect(kills).toBe(1);
  });
